INSERT INTO "ContentSection" ("id", "section_key", "title", "subtitle", "body", "image_url", "status", "sort_order", "updated_at") VALUES (1, 'hero', 'Fast Local Reliable Parcel & Goods Delivery', 'Book in 2 minutes', 'Parcel delivery, goods vehicles, water tankers, construction material, machinery rental and packed ration — all from one app.', NULL, 'Active', 1, '2026-07-06T19:57:47.436Z');
INSERT INTO "ContentSection" ("id", "section_key", "title", "subtitle", "body", "image_url", "status", "sort_order", "updated_at") VALUES (2, 'how_it_works', 'How It Works', 'Book in 3 simple steps', '1. Choose your service and vehicle.
INSERT INTO "ContentSection" ("id", "section_key", "title", "subtitle", "body", "image_url", "status", "sort_order", "updated_at") VALUES (3, 'about', 'About ParcelMaadi', 'By HP Enterprise', 'ParcelMaadi by HP Enterprise is your local partner for parcel, courier, goods vehicles, water tankers and construction material. We connect customers with reliable drivers and suppliers across Karnataka.', NULL, 'Active', 3, '2026-07-06T19:57:47.438Z');
INSERT INTO "ContentSection" ("id", "section_key", "title", "subtitle", "body", "image_url", "status", "sort_order", "updated_at") VALUES (4, 'faq', 'Frequently Asked Questions', '', 'Q: Do you provide rider app? A: Not yet. Admin assigns drivers manually.
INSERT INTO "ContentSection" ("id", "section_key", "title", "subtitle", "body", "image_url", "status", "sort_order", "updated_at") VALUES (5, 'terms', 'Terms & Conditions', 'HP Enterprise', '1. By booking with ParcelMaadi (operated by HP Enterprise, GSTIN 29ANZPH4067Q1ZS) you agree to these terms.
INSERT INTO "ContentSection" ("id", "section_key", "title", "subtitle", "body", "image_url", "status", "sort_order", "updated_at") VALUES (6, 'privacy', 'Privacy Policy', 'HP Enterprise', '1. ParcelMaadi (HP Enterprise) collects only the information needed to fulfil your booking — name, mobile, pickup and drop locations, and item details.
INSERT INTO "ContentSection" ("id", "section_key", "title", "subtitle", "body", "image_url", "status", "sort_order", "updated_at") VALUES (7, 'refund', 'Refund & Cancellation Policy', 'HP Enterprise', '1. You can cancel a booking free of charge before the admin confirms it.
INSERT INTO "ContentSection" ("id", "section_key", "title", "subtitle", "body", "image_url", "status", "sort_order", "updated_at") VALUES (8, 'trust', 'Trusted by Local Businesses', '', 'Hundreds of retailers, builders and families across Karnataka trust ParcelMaadi for fast, reliable and affordable logistics.', NULL, 'Active', 8, '2026-07-06T19:57:47.441Z');
